package com.example.quizella.domain.model

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * User entity representing a registered user in the application.
 *
 * @property id Unique identifier for the user, auto-generated by Room.
 * @property username Unique username chosen by the user.
 * @property passwordHash Securely hashed password using SHA-256.
 */
@Entity(tableName = "users")
data class User(
    @PrimaryKey(autoGenerate = true)
    val id: Int = 0,
    val username: String,
    val passwordHash: String
)